/* gen_h.js - hand-written MCQ banks for four first-semester BCA subjects (VMSB UTU Bachelor of Computer Applications):
   BCA-004 IT Fundamentals, BCA-005 Personality Development and Life Skills, BCA-010 Environmental Studies,
   BCA-011 Bridge Course in Mathematics. Units follow src/content/syllabus/BCA-0NN.json.
   Same pattern as gen_g.js: static questions are written by hand (right answer, three plausible wrong answers, one-line
   explanation); parametrised ones compute their answer and, when globalThis.__GEN_VERIFY__ is set, re-check it with a second
   (brute-force) method. Reuses bq/bcN/BC_VERIFY/bcGcd/bcFact/bcBin/bcC/bcP from gen_g.js; own helpers are prefixed bh. */
const bhFlip=(s,i)=>s.slice(0,i)+(s[i]==="0"?"1":"0")+s.slice(i+1);
const bhFrac=(n,d)=>{const g=bcGcd(Math.abs(n),Math.abs(d))||1;n/=g;d/=g;if(d<0){n=-n;d=-d}return d===1?String(n):n+"/"+d};
/* string answer (binary, fractions, points) with four candidate wrong values, of which three distinct ones are used */
const bhStr=(q,ans,cand,why)=>{const set=[];for(const c of cand)if(c!==ans&&!set.includes(c))set.push(c);return mcq(q,ans,set.slice(0,3),why)};
const bhPoly=(a,b,n)=>{const c=[];for(let r=0;r<=n;r++)c.push(bcC(n,r)*a**(n-r)*b**r);return c};
const bhDet3=m=>m[0][0]*(m[1][1]*m[2][2]-m[1][2]*m[2][1])-m[0][1]*(m[1][0]*m[2][2]-m[1][2]*m[2][0])+m[0][2]*(m[1][0]*m[2][1]-m[1][1]*m[2][0]);
const bhSarrus=m=>m[0][0]*m[1][1]*m[2][2]+m[0][1]*m[1][2]*m[2][0]+m[0][2]*m[1][0]*m[2][1]-m[0][2]*m[1][1]*m[2][0]-m[0][0]*m[1][2]*m[2][1]-m[0][1]*m[1][0]*m[2][2];
const bhMat=m=>"["+m.map(r=>r.join(" ")).join("; ")+"]";
const bhMean=a=>a.reduce((x,y)=>x+y,0)/a.length;
const bhSumSq=(a,m)=>a.reduce((s,x)=>s+(x-m)*(x-m),0);
const bhHex=n=>n.toString(16).toUpperCase();

